// ============================================================
// MODÈLE PRÉVISION PONDÉRÉ — WF-2.5 (version robuste)
// Auto-détection des noms de colonnes Google Sheets
// ============================================================

const historiqueRaw = $('Sheets — Lire historique participation').all().map(i => i.json);
const activitesRaw  = $input.all().map(i => i.json);

if (!activitesRaw.length) return [];

// ── Auto-détection de colonne (insensible à la casse, accents, espaces) ──────
function findKey(obj, candidates) {
  const keys = Object.keys(obj);
  for (const c of candidates) {
    const cNorm = c.toLowerCase().replace(/[\s_\-éèêàùû]/g, '');
    const found = keys.find(k => k.toLowerCase().replace(/[\s_\-éèêàùû]/g, '') === cNorm);
    if (found !== undefined) return found;
  }
  // Fallback : partial match
  for (const c of candidates) {
    const cNorm = c.toLowerCase().replace(/[\s_\-éèêàùû]/g, '');
    const found = keys.find(k => k.toLowerCase().replace(/[\s_\-éèêàùû]/g, '').includes(cNorm.slice(0,5)));
    if (found !== undefined) return found;
  }
  return null;
}

function get(obj, candidates) {
  const key = findKey(obj, candidates);
  return key ? obj[key] : undefined;
}

// Nommer les champs historique
const historique = historiqueRaw.map(h => ({
  date:          get(h, ['date','date_activite','Date','Date activité']),
  type_activite: get(h, ['type_activite','type','Type','type activite','TypeActivite']),
  unite:         get(h, ['unite','unité','Unite','Unité','unit']),
  taux_reel:     get(h, ['taux_reel','taux_réel','taux','TauxReel','Taux réel','Taux']),
  nom_activite:  get(h, ['nom_activite','nom','Nom','nom activite','NomActivite']),
  inscrits:      get(h, ['inscrits','Inscrits','nb_inscrits']),
  presents:      get(h, ['presents','présents','Présents','nb_presents']),
}));

// Nommer les champs activités
const activites = activitesRaw.map(a => ({
  date_activite:  get(a, ['date_activite','date','Date','Date activité']),
  mois_activite:  get(a, ['mois_activite','mois','Mois','mois activite']),
  nom_activite:   get(a, ['nom_activite','nom','Nom','nom activite','Activité','activite']),
  type_activite:  get(a, ['type_activite','type','Type','type activite']),
  unite:          get(a, ['unite','unité','Unite','Unité']),
  capacite_max:   get(a, ['capacite_max','capacité_max','capacite','capacité','Capacité','Capacite','capacite max','nb_max','max']),
  _raw:           a
}));

// ── Saison ────────────────────────────────────────────────────────────────────
const moisCourant = new Date().getMonth() + 1;
function getSaison(m) {
  if ([12,1,2].includes(m)) return 'hiver';
  if ([3,4,5].includes(m))  return 'printemps';
  if ([6,7,8].includes(m))  return 'ete';
  return 'automne';
}
const saisonCourante = getSaison(moisCourant);

function getSaisonFromDate(dateStr) {
  if (!dateStr) return 'inconnu';
  const d = new Date(dateStr);
  if (isNaN(d)) return 'inconnu';
  return getSaison(d.getMonth() + 1);
}

// ── Moyenne pondérée par type ─────────────────────────────────────────────────
function moyennePonderee(type, unite) {
  const toNum = v => { const n = parseFloat(String(v).replace(',','.')); return isNaN(n) ? null : n; };

  // Tenter de calculer taux depuis inscrits/presents si taux_reel absent
  const lignesType = historique.filter(h => {
    if (!h.type_activite) return false;
    const ht = h.type_activite.toLowerCase().trim();
    const at = (type || '').toLowerCase().trim();
    return ht === at || ht.includes(at) || at.includes(ht);
  });

  const avecTaux = lignesType.map(h => {
    let taux = toNum(h.taux_reel);
    // Calculer depuis inscrits/presents si taux absent
    if (taux === null) {
      const ins = toNum(h.inscrits);
      const pre = toNum(h.presents);
      if (ins && pre && ins > 0) taux = Math.round((pre / ins) * 100);
    }
    // Taux en décimal (0-1) → convertir
    if (taux !== null && taux <= 1) taux = Math.round(taux * 100);
    return { ...h, tauxNum: taux };
  }).filter(h => h.tauxNum !== null && h.tauxNum >= 0 && h.tauxNum <= 100);

  if (!avecTaux.length) {
    // Aucune donnée pour ce type → fallback global
    const global = historique.map(h => {
      let t = toNum(h.taux_reel);
      if (t === null) {
        const ins = toNum(h.inscrits); const pre = toNum(h.presents);
        if (ins && pre && ins > 0) t = Math.round((pre / ins) * 100);
      }
      if (t !== null && t <= 1) t = Math.round(t * 100);
      return t;
    }).filter(t => t !== null && t >= 0 && t <= 100);

    if (!global.length) return 72; // valeur par défaut réaliste
    return Math.round(global.reduce((s,v) => s+v, 0) / global.length);
  }

  let sommePoids = 0, sommeVal = 0;
  avecTaux.forEach(h => {
    const saison = getSaisonFromDate(h.date);
    const poids  = saison === saisonCourante ? 2 : 1;
    sommeVal   += h.tauxNum * poids;
    sommePoids += poids;
  });
  return Math.round(sommeVal / sommePoids);
}

// ── Tendance ─────────────────────────────────────────────────────────────────
function calculTendance(type) {
  const now = new Date();
  const m3  = new Date(now); m3.setMonth(now.getMonth() - 3);
  const m6  = new Date(now); m6.setMonth(now.getMonth() - 6);
  const toNum = v => { const n = parseFloat(String(v||'').replace(',','.')); return isNaN(n) ? null : n; };

  const lignesType = historique.filter(h => {
    if (!h.type_activite || !h.date) return false;
    const ht = h.type_activite.toLowerCase().trim();
    const at = (type||'').toLowerCase().trim();
    return ht === at || ht.includes(at) || at.includes(ht);
  });

  const withDate = lignesType.map(h => {
    let t = toNum(h.taux_reel);
    if (t === null) {
      const ins = toNum(h.inscrits); const pre = toNum(h.presents);
      if (ins && pre && ins > 0) t = Math.round((pre / ins) * 100);
    }
    if (t !== null && t <= 1) t = Math.round(t * 100);
    return { date: new Date(h.date), taux: t };
  }).filter(h => !isNaN(h.date) && h.taux !== null);

  const recents = withDate.filter(h => h.date >= m3);
  const anciens  = withDate.filter(h => h.date >= m6 && h.date < m3);

  if (!recents.length || !anciens.length) return { label: 'stable', ajustement: 0 };

  const moyR = recents.reduce((s,h) => s + h.taux, 0) / recents.length;
  const moyA = anciens.reduce((s,h) => s + h.taux, 0) / anciens.length;
  const diff = moyR - moyA;
  if (diff > 3)  return { label: 'hausse',  ajustement: +3 };
  if (diff < -3) return { label: 'baisse',  ajustement: -3 };
  return               { label: 'stable', ajustement:  0 };
}

// ── Prévision par activité ────────────────────────────────────────────────────
const moisSuivant = new Date();
moisSuivant.setMonth(moisSuivant.getMonth() + 1);
const periodeLabel = moisSuivant.toLocaleDateString('fr-FR', { month: 'long', year: 'numeric' });

return activites.map(act => {
  const type     = (act.type_activite || '').trim();
  const unite    = (act.unite || '').trim();
  const capacite = parseFloat(String(act.capacite_max || '0').replace(',','.')) || 0;

  const base     = moyennePonderee(type, unite);
  const tendance = calculTendance(type);
  const taux     = Math.min(100, Math.max(0, Math.round(base + tendance.ajustement)));
  const presence = capacite > 0 ? Math.round((taux / 100) * capacite) : 0;
  const alerte   = taux < 60;

  return {
    json: {
      periode:         periodeLabel,
      nom_activite:    act.nom_activite    || act._raw[Object.keys(act._raw)[1]] || 'N/A',
      date_activite:   act.date_activite   || '',
      mois_activite:   act.mois_activite   || '',
      type_activite:   type                || '',
      unite:           unite               || '',
      capacite_max:    capacite,
      taux_prevu:      taux,
      presence_prevue: presence,
      tendance:        tendance.label,
      alerte,
      taux_reel:       '',
      ecart:           ''
    }
  };
});

// ============================================================
// GÉNÈRE RAPPORT HTML MENSUEL — WF-2.5
// ============================================================
const items = $input.all().map(i => i.json);
if (!items.length) return [{ json: { html: '<p>Aucune prévision disponible.</p>', mois: '', taux_moyen: 0, alertes: 0 } }];

// Sheets retourne alerte comme string "OUI"/"NON" — convertir en booléen
const parseAlerte = v => {
  if (typeof v === 'boolean') return v;
  if (typeof v === 'string') return v.trim().toUpperCase() === 'OUI';
  return !!v;
};

const parseTaux = v => {
  const n = parseFloat(String(v ?? '').replace(',', '.'));
  return isNaN(n) ? null : n;
};

const parsed = items.map(i => ({
  ...i,
  taux_prevu:  parseTaux(i.taux_prevu),
  alerte:      parseAlerte(i.alerte),
  capacite_max: parseFloat(i.capacite_max) || 0,
}));

const valid     = parsed.filter(i => i.taux_prevu !== null);
const alertes   = parsed.filter(i => i.alerte).length;
const tauxMoyen = valid.length
  ? Math.round(valid.reduce((s,i) => s + i.taux_prevu, 0) / valid.length)
  : 0;
const mois = items[0]?.periode || '';

const clr = t => t >= 80 ? '#1a7340' : t >= 60 ? '#e67e22' : '#c0392b';
const bar = t => {
  const pct = Math.min(t, 100);
  return `<div style="background:#eee;border-radius:4px;height:8px;width:100%;">
    <div style="background:${clr(t)};height:8px;border-radius:4px;width:${pct}%;"></div></div>`;
};
const safe = v => (v === undefined || v === null || v === '') ? '—' : v;

const lignes = parsed.map(i => {
  const t   = i.taux_prevu;
  const bg  = i.alerte ? '#fdecea' : '#f0faf4';
  const tc  = t !== null ? clr(t) : '#888';
  return `<tr style="background:${bg};">
    <td style="padding:8px;">${safe(i.date_activite)}</td>
    <td style="padding:8px;font-weight:500;">${safe(i.nom_activite)}</td>
    <td style="padding:8px;">${safe(i.type_activite)}</td>
    <td style="padding:8px;">${safe(i.unite)}</td>
    <td style="padding:8px;text-align:right;">${safe(i.capacite_max || '')}</td>
    <td style="padding:8px;text-align:right;">
      <strong style="color:${tc};">${t !== null ? t+'%' : '—'}</strong><br>
      ${t !== null ? bar(t) : ''}</td>
    <td style="padding:8px;text-align:right;">${safe(i.presence_prevue)}</td>
    <td style="padding:8px;">${safe(i.tendance)}</td>
    <td style="padding:8px;text-align:center;font-weight:600;color:${i.alerte ? '#c0392b' : '#1a7340'};">
      ${i.alerte ? '⚠ ALERTE' : '✓ OK'}</td>
  </tr>`;
}).join('');

const html = `
<div style="font-family:Arial,sans-serif;max-width:800px;">
  <div style="background:#2c5f2e;color:white;padding:16px 20px;border-radius:8px 8px 0 0;">
    <h2 style="margin:0;font-size:18px;">Prévisions participation — ${mois}</h2>
    <p style="margin:4px 0 0;font-size:13px;opacity:0.85;">
      ${parsed.length} activité(s) · Taux moyen prévu : ${tauxMoyen}% · ${alertes} alerte(s)
    </p>
  </div>
  <div style="display:flex;gap:12px;padding:16px;background:#f9f9f9;">
    <div style="flex:1;text-align:center;background:white;padding:12px;border-radius:8px;">
      <div style="font-size:11px;color:#888;">Activités planifiées</div>
      <div style="font-size:24px;font-weight:600;color:#2c5f2e;">${parsed.length}</div>
    </div>
    <div style="flex:1;text-align:center;background:white;padding:12px;border-radius:8px;">
      <div style="font-size:11px;color:#888;">Taux moyen prévu</div>
      <div style="font-size:24px;font-weight:600;color:${clr(tauxMoyen)};">${tauxMoyen}%</div>
    </div>
    <div style="flex:1;text-align:center;background:white;padding:12px;border-radius:8px;">
      <div style="font-size:11px;color:#888;">Alertes (&lt; 60%)</div>
      <div style="font-size:24px;font-weight:600;color:${alertes > 0 ? '#c0392b' : '#1a7340'};">${alertes}</div>
    </div>
  </div>
  <table border="1" cellpadding="0" cellspacing="0"
    style="border-collapse:collapse;width:100%;font-size:13px;">
    <thead>
      <tr style="background:#2c5f2e;color:white;">
        <th style="padding:8px;">Date</th><th style="padding:8px;">Activité</th>
        <th style="padding:8px;">Type</th><th style="padding:8px;">Unité</th>
        <th style="padding:8px;">Capacité</th><th style="padding:8px;">Taux prévu</th>
        <th style="padding:8px;">Présences</th><th style="padding:8px;">Tendance</th>
        <th style="padding:8px;">Statut</th>
      </tr>
    </thead>
    <tbody>${lignes}</tbody>
  </table>
  <p style="font-size:12px;color:#666;padding:8px;">
    Modèle : moyenne historique pondérée par type · saison courante ×2 · ajustement tendance ±3%.<br>
    Remplissez <em>taux_reel</em> après chaque activité pour améliorer le modèle au fil du temps.
  </p>
</div>`;

return [{ json: { html, mois, taux_moyen: tauxMoyen, alertes } }];
